import { useEffect, useState } from "react";
import { extractErrorMessage } from "../api/axios";

export function useLookupOptions(fetchFn, mapper) {
  const [options, setOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let mounted = true;

    async function loadOptions() {
      setIsLoading(true);
      setError("");

      try {
        const response = await fetchFn();

        if (!mounted) return;

        const responseData = response?.data;

        let list = [];

        // Backend returns:
        // { success: true, students: [...] }
        if (Array.isArray(responseData?.students)) {
          list = responseData.students;
        }

        // Backend may return:
        // { success: true, courses: [...] }
        else if (Array.isArray(responseData?.courses)) {
          list = responseData.courses;
        }

        // Generic response:
        else if (Array.isArray(responseData?.data)) {
          list = responseData.data;
        }

        // Direct array response
        else if (Array.isArray(responseData)) {
          list = responseData;
        }

        else if (Array.isArray(responseData?.items)) {
          list = responseData.items;
        }

        const mappedOptions = list
          .map((item) => {
            try {
              return mapper(item);
            } catch {
              return null;
            }
          })
          .filter(Boolean);

        setOptions(mappedOptions);
      } catch (err) {
        if (!mounted) return;

        setOptions([]);

        const message = extractErrorMessage(
          err,
          "Unable to load options."
        );

        setError(message);
      } finally {
        if (mounted) {
          setIsLoading(false);
        }
      }
    }

    loadOptions();

    return () => {
      mounted = false;
    };
  }, [fetchFn, mapper]);

  return {
    options,
    isLoading,
    error
  };
}
